{
 "app_name": "simple_note",
 "api_name": "search_notes",
 "path": "/notes",
 "method": "GET",
 "description": "Search your notes. This will not show contents of the notes. Pinned notes will be shown first by default, except when dont_reorder_pinned is true.",
 "parameters": [
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from simple_note app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "query",
   "type": "string",
   "required": false,
   "description": "Search query for the notes.",
   "default": "",
   "constraints": []
  },
  {
   "name": "tags",
   "type": "list[string]",
   "required": false,
   "description": "Tags to filter the notes by. Notes not having any of these tags will be filtered out.",
   "default": null,
   "constraints": []
  },
  {
   "name": "pinned",
   "type": "boolean",
   "required": false,
   "description": "Filter notes by pinned status.",
   "default": null,
   "constraints": []
  },
  {
   "name": "dont_reorder_pinned",
   "type": "boolean",
   "required": false,
   "description": "If true, pinned notes will not be reordered to be shown at the top.",
   "default": null,
   "constraints": []
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0.0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1.0, <= 20.0"
   ]
  },
  {
   "name": "sort_by",
   "type": "string",
   "required": false,
   "description": "The attribute to sort the notes by prefixed with +/- to reflect ascending/descending. Valid attributes: created_at and updated_at. If both query and sort_by are given and non-empty, results will be first ranked by query relevance, then paginated, and will then be sorted by the given attribute within each page. If both query and sort_by are not given, null, or empty, sort_by will default to -updated_at.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": [
   {
    "note_id": 1,
    "title": "string",
    "tags": [
     "string"
    ],
    "created_at": "2019-01-01T00:00:00",
    "updated_at": "2019-01-01T00:00:00",
    "pinned": true
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}

{
 "app_name": "todoist",
 "api_name": "show_tasks",
 "path": "/projects/{project_id}/tasks",
 "method": "GET",
 "description": "Get a list of tasks within a project.",
 "parameters": [
  {
   "name": "project_id",
   "type": "integer",
   "required": true,
   "description": "The ID of the project. You can use 0 for your Inbox project.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from todoist app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "section_id",
   "type": "integer",
   "required": false,
   "description": "The ID of the section to filter tasks by. Set it to 0 for tasks without a section.",
   "default": null,
   "constraints": []
  },
  {
   "name": "assignee_email",
   "type": "string",
   "required": false,
   "description": "Email address of the assignee to filter tasks by.",
   "default": null,
   "constraints": [
    "value is email address"
   ]
  },
  {
   "name": "assigner_email",
   "type": "string",
   "required": false,
   "description": "Email address of the assigner to filter tasks by.",
   "default": null,
   "constraints": [
    "value is email address"
   ]
  },
  {
   "name": "priority",
   "type": "string",
   "required": false,
   "description": "The priority to filter tasks by.",
   "default": null,
   "constraints": [
    "value in ['high', 'medium', 'low']"
   ]
  },
  {
   "name": "is_completed",
   "type": "boolean",
   "required": false,
   "description": "Completion status to filter by.",
   "default": null,
   "constraints": []
  },
  {
   "name": "due_today",
   "type": "boolean",
   "required": false,
   "description": "If true, only tasks due today will be returned. If false, all tasks will be returned.",
   "default": false,
   "constraints": []
  },
  {
   "name": "label_id",
   "type": "integer",
   "required": false,
   "description": "The ID of the label to filter tasks by.",
   "default": null,
   "constraints": []
  },
  {
   "name": "overdue",
   "type": "boolean",
   "required": false,
   "description": "If true, only tasks that are overdue will be returned. If false, all tasks will be returned.",
   "default": false,
   "constraints": []
  },
  {
   "name": "min_due_date",
   "type": "string",
   "required": false,
   "description": "Only tasks with a due date greater than or equal to this date will be returned. Date should be in YYYY-MM-DD format.",
   "default": "1500-01-01",
   "constraints": []
  },
  {
   "name": "max_due_date",
   "type": "string",
   "required": false,
   "description": "Only tasks with a due date less than or equal to this date will be returned. Date should be in YYYY-MM-DD format.",
   "default": "3000-01-01",
   "constraints": []
  },
  {
   "name": "sort_by",
   "type": "string",
   "required": false,
   "description": "The attribute to sort the tasks by prefixed with +/- to reflect ascending/descending. Valid attributes: order_index, due_date and priority.",
   "default": "+order_index",
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "project_id": 1,
   "no_section_tasks": [
    {
