     "assignee_id": 1,
     "labels": [
      {
       "id": 1,
       "color": "string",
       "name": "string"
      }
     ]
    }
   ],
   "sections": [
    {
     "section_id": 1,
     "tasks": [
      {
       "order_index": 1,
       "task_id": 1,
       "title": "string",
       "description": "string",
       "num_sub_tasks": 1,
       "is_completed": true,
       "due_date": "2019-01-01T00:00:00",
